"""Money arithmetic for invoices."""
from decimal import Decimal, ROUND_HALF_UP

CENTS = Decimal("0.01")


def _decimal(value):
    if isinstance(value, Decimal):
        return value
    return Decimal(str(value))


def line_total(qty, unit_price):
    amount = _decimal(qty) * _decimal(unit_price)
    return amount.quantize(CENTS, rounding=ROUND_HALF_UP)


def total(lines):
    return sum(
        (line_total(l["qty"], l["unit_price"]) for l in lines),
        Decimal("0.00"),
    )

import io
import json
import os
import tempfile
import unittest
from contextlib import redirect_stderr, redirect_stdout

from invoicer.cli import main

INVOICE = {
    "client": "Acme",
    "lines": [
        {"item": "Hosting", "qty": "3", "unit_price": "1.115"},
        {"item": "Support", "qty": "1", "unit_price": "2.675"},
    ],
}


class TestCli(unittest.TestCase):
    def setUp(self):
        fd, self.path = tempfile.mkstemp(suffix=".json")
        with os.fdopen(fd, "w") as f:
            json.dump(INVOICE, f)
        self.addCleanup(os.unlink, self.path)

    def _run(self, *argv):
        buf = io.StringIO()
        err = io.StringIO()
        with redirect_stdout(buf), redirect_stderr(err):
            main(list(argv))
        return buf.getvalue().strip()

    def test_default_currency_is_eur(self):
        self.assertEqual(self._run(self.path), "Acme: \u20ac5.36")

    def test_usd(self):
        self.assertEqual(self._run(self.path, "--currency", "USD"), "Acme: $5.36")

    def test_gbp(self):
        self.assertEqual(self._run(self.path, "--currency", "GBP"), "Acme: \u00a35.36")

    def test_unknown_currency_is_an_error(self):
        with self.assertRaises(SystemExit):
            with redirect_stderr(io.StringIO()):
                main([self.path, "--currency", "JPY"])


if __name__ == "__main__":
    unittest.main()

import csv
import io
import unittest

from invoicer.export import to_csv

INVOICE = {
    "client": "Brightwell",
    "lines": [
        {"item": "Design, phase 2", "qty": "2", "unit_price": "410.125"},
        {"item": 'Review "final"', "qty": "1", "unit_price": "99.995"},
    ],
}


class TestExport(unittest.TestCase):
    def test_header_and_rows(self):
        rows = list(csv.reader(io.StringIO(to_csv(INVOICE))))
        self.assertEqual(rows[0], ["item", "qty", "unit_price", "line_total"])
        self.assertEqual(
            rows[1], ["Design, phase 2", "2", "410.125", "820.25"]
        )
        self.assertEqual(
            rows[2], ['Review "final"', "1", "99.995", "100.00"]
        )

    def test_two_decimals_on_line_total(self):
        invoice = {
            "client": "Corvid Ltd",
            "lines": [{"item": "Licences", "qty": "12", "unit_price": "8.3333"}],
        }
        rows = list(csv.reader(io.StringIO(to_csv(invoice))))
        self.assertEqual(rows[1], ["Licences", "12", "8.3333", "100.00"])

    def test_returns_string_and_ends_with_newline(self):
        out = to_csv(INVOICE)
        self.assertIsInstance(out, str)
        self.assertTrue(out.endswith("\n"))


if __name__ == "__main__":
    unittest.main()
